// Typed access to the JSON generated by scripts/extract-rathena.ts.

import jobsJson from "../data/jobs.json";
import statPointsJson from "../data/statPoints.json";

export type StatName = "Str" | "Agi" | "Vit" | "Int" | "Dex" | "Luk";
export const STAT_NAMES: readonly StatName[] = ["Str", "Agi", "Vit", "Int", "Dex", "Luk"];

export type JobName = "Novice_High" | "Swordman_High" | "Knight" | "Lord_Knight";

export interface JobData {
  job: JobName;
  baseAspd: Partial<Record<string, number>>;
  bonusStats: { level: number; stats: Partial<Record<StatName, number>> }[];
}

export const jobs = jobsJson as JobData[];

/** Cumulative status points by base level (index = level - 1), before the transcendent bonus. */
export const statPoints: readonly number[] = statPointsJson;

export function getJob(job: JobName): JobData {
  const data = jobs.find((j) => j.job === job);
  if (!data) throw new Error(`Unknown job ${job}`);
  return data;
}
